CREATE OR REPLACE FUNCTION public.trg_application_notify()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT part_id FROM part_application WHERE application_id = COALESCE(NEW.application_id, OLD.application_id) LOOP
    PERFORM notify_meili_upsert_for_part(r.part_id);
  END LOOP;
  -- Also notify applications index to refresh this application doc
  PERFORM pg_notify('meili_app_sync', json_build_object('action', CASE WHEN TG_OP = 'DELETE' THEN 'delete' ELSE 'upsert' END, 'application_id', COALESCE(NEW.application_id, OLD.application_id))::text);
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_engine_rename_notify()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r RECORD;
BEGIN
    IF NEW.engine_code IS DISTINCT FROM OLD.engine_code THEN
        FOR r IN SELECT application_id FROM application WHERE engine_id = NEW.engine_id LOOP
            PERFORM notify_application_change(r.application_id);
        END LOOP;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_catalog_child_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM log_catalog_change(COALESCE(NEW.part_id, OLD.part_id), 'upsert');
  RETURN COALESCE(NEW, OLD);
END;
$function$

