CREATE OR REPLACE FUNCTION public.lock_part_merge_rows()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    record_json JSONB;
    candidate TEXT;
BEGIN
    FOREACH record_json IN ARRAY ARRAY[
        CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END,
        CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END
    ]
    LOOP
        IF record_json IS NULL THEN CONTINUE; END IF;
        FOR candidate IN
            SELECT value
            FROM (
                SELECT DISTINCT value, value::bigint AS lock_id
                FROM unnest(ARRAY[
                    record_json ->> 'part_id',
                    record_json ->> 'source_part_id',
                    record_json ->> 'part_id_1',
                    record_json ->> 'part_id_2'
                ]) AS value
                WHERE value IS NOT NULL
            ) locks
            ORDER BY lock_id
        LOOP
            PERFORM pg_advisory_xact_lock(candidate::bigint);
        END LOOP;
    END LOOP;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$

